      outlook: "【8/3朝7:00更新】朝時点で最も重い事実は、7/31の米国市場が続伸したにもかかわらずCME日経先物(円建て9月限)が大阪日中終値比-450円で引けたことである。金曜の+4.03%・2,494円高をそのまま引き継ぐ地合いではなく、寄りはむしろ利益確定売りが出やすい前提で見ておきたい。理由は為替で、週末に判明した日米協調介入(7/30分だけで6〜7兆円規模との推計)に加え、本日8/3に日米共同声明が発表される予定と報じられている。声明の文言次第でドル円がさらに振れる可能性があり、輸出・外需株には直接の逆風、内需・輸入コスト依存の銘柄には相対的な追い風という構図が金曜より強まっている。セクターの中身も金曜と変わった。アップルが7-9月期見通し未達で-7.35%と急落しており、金曜にストップ高比例配分で引けた村田製作所などアップル関連には巻き戻しが出やすい。一方でアマゾンはAWS売上+36.7%・26年設備投資2,200億ドルへの引き上げを発表して急伸しており、データセンター・NAND需要の文脈は支援材料になる。つまり金曜に一括りで買い戻された「AI・半導体」が、本日はアップル系とデータセンター系で選別される可能性がある。SOX指数は+0.07%とほぼ横ばい、マイクロンは-5.90%で、半導体全体に勢いが続いているとは言えない。以下は前日夕方時点の見立てで、内容は現時点でも有効である。8/3(月)の最大の変数は2つある。1つはキオクシアの決算で、同社は7/31にストップ高46,500円の比例配分で引けた直後の15:30に4-6月期決算を発表し、純利益は前年同期比46倍ながら会社予想8,690億円に未達、7-9月期予想1兆2,700億円も市場予想1兆3,400億円前後に届かなかった。同時に最大8,000億円の自社株買い(取得期間8/3〜10/30)と1対3の株式分割も発表しており、夜間PTSでは売買代金92.6億円と全銘柄で突出した商いを伴って-3.96%まで売られている。同社の寄り付きの反応がAI・半導体関連全体のセンチメントを左右する可能性が高い。もう1つは為替で、介入とみられる急落の後も円高方向の圧力が続き18時時点で158円73銭まで進んでおり、輸出・外需株には逆風が強まっている。国内は8/3から決算発表がピークを迎え、8/3は三菱商事・伊藤忠・日産自動車・エーザイなど83社、8/4はトヨタ・イビデン・ソフトバンクなど89社、8/5は178社、8/6は任天堂・ソフトバンクGなど322社、8/7は672社と、指数よりも個別のイベントで動く週になる。米雇用統計は通例どおりなら8/7(金)発表の見込み(日程の最終確認は取れていない)。テクニカルには7/29安値6万448円が下値支持として意識され、株探の来週予想レンジは6万1,500〜6万6,000円。値上がり612対値下がり922という極端な物色の偏りが続いており、指数の大幅高だけを見て地合い良好と判断するのは危険で、AI・半導体以外のセクターでは戻り売りが優勢になりやすい点は変わっていない。【朝の追記・本日の日程】決算は83社で、三菱商事が14:00と場中発表のため商社セクターは後場に振れやすい。ほかに伊藤忠商事・丸紅・日産自動車・三菱UFJ FG・エーザイなど。国内は14:00に7月新車・軽自動車販売、海外は23:00に米7月ISM製造業景況指数。今週は8/4トヨタ・ソフトバンクG(89社)、8/5が178社、8/6任天堂・NTT(322社)、8/7が672社と後半に決算が集中し、最大の焦点は8/7(金)21:30の米7月雇用統計。米雇用統計は前回6月分が非農業部門雇用者数+5.7万人と弱く、過去2カ月分も計7.4万人下方修正されている。ザイ・オンラインの今週の日経平均予想レンジは61,000〜68,000円と7,000円幅で、レンジの広さ自体が不確実性の高さを示している。株探の週末コメントでは上値は13週線66,032円、下値は26週線61,124円が意識されるとしている。",
