          scenario: "材料の質は本日の上位で、SNSでも最も話題を集めている銘柄の一つ。しかし本日の答え合わせでも確認されたとおり、この銘柄は寄りから引けまで一度も値が動かない比例配分で、実質的にエントリーもエグジットも成立しなかった。翌営業日も同じ状態が続く可能性が高く、売買代金2.56億円は当サイトの流動性ルール(買い/売りプランは当日売買代金10億円以上)を大きく下回るため、材料の強さにかかわらずプラン化の対象にならない。PTSで+20%さらに買われているのは強気の表れだが、PTS出来高も26,700株と薄く、値位置の信頼度は低い。【8/3朝更新】夜間を通じてPTSは株探17:30時点の24,900円(+17.7%)から最終25,500円(+20.57%)へさらに水準を切り上げており、東証終値がストップ高で頭打ちだったぶんPTSが「制限値幅を超えた本来の需給」を示している可能性は高い。ただしそれは翌朝も特別気配で始まりやすいことを意味するだけで、売買代金2.56億円という流動性ルール(10億円以上)を満たさない事実は何も変わらない。見送り判断は据え置く。",
          entry: "見送りが基本。特別気配が出た場合はそれが解消して値がつくまで手を出さない。取る場合も寄り成行は絶対に使わず、値がついた後に寄り値を維持して出来高を伴い上値を切り上げるのを確認してから。",
          invalidation: "積極的なエントリーは見送り前提。評価を改めるとすれば、寄り後に平常の出来高が戻り、板が売買を受け止められる厚さになったことが確認できた場合に限られる。",
          risk: "見送りが外れる側のリスクは、メモリ市況というテーマ全体に資金が入り続けて3日連続のストップ高になる展開。逆に手を出した場合のリスクは、板の薄さによる約定の滑りと、寄りで値がつかないまま資金が拘束されること、そして高値圏で値がついた直後に急落する往って来い。連続S高の後は制限値幅が拡大されることもあり、下振れした場合の値幅も大きくなる。"
