            detail: "7/29 15:30発表。1Q(4-6月)は売上高3,674億円(前年同期比+39.3%)、営業利益1,899億円(+53.3%)、最終利益1,747億円(+93.8%)。通期は売上高1兆4,200億円→1兆7,140億円(+20.7%)、営業益6,275億円→8,460億円(+34.8%)へ増額し、最終増益率は24.0%増→75.8%増に拡大した。1Qの売上営業利益率は47.0%→51.7%へ上昇。夜間PTSは27,754円(東証終値25,200円比+2,554円・+10.13%)と急伸しPTS上昇率上位に入った。修正理由は『推論用AI半導体向けテスト需要が想定を大きく上回る』。【朝7:00更新】夜間PTSの確定値は27,560円(+9.37%、出来高72,100株)で夕方時点から約194円値を消した。ADR(ATEYY)は終値165.00ドル(+6.08%)だが、始値171.90ドル・高値177.06ドル(+13%相当)から失速して引けている。期待された『SOX指数の流れを変える材料になるか』は否定され、SOX指数は反転せず-5.33%と5日続落で下げが加速した。",
