            detail: "7/29 16:00発表。1Q(4-6月)の連結経常利益は前年同期比3.1倍の52.2億円に急拡大し、1Qの売上営業利益率は9.0%→18.6%へ急改善した。上期経常は前年同期36億円に対し2.1倍へ、通期は売上高840億円→970億円、経常110億円→126億円(前期比+21.5%)、最終67億円→77億円に増額。年間配当150円は据え置き。AI向けハイエンドサーバー用の低誘電樹脂が国内外で大幅増となったことが牽引役で、同社は供給体制強化に向けた設備投資も決定している。夜間PTSは10,330円(東証終値8,830円比+16.99%)でPTS上昇率トップ。【朝7:00更新】決算とは別建てで『低誘電樹脂材料に約100億円の設備投資(27年度以降稼働)』を7/29 16:00に開示していたことを確認。一方でPTSの+16.99%は夜間出来高がわずか2,300株(概算2,376万円)・最終約定22:17での値付けであり、寄り値の予測材料としては極めて薄い点に注意。株探7/30 07:01の『本日注目すべき好決算銘柄』には掲載されている。",
