            detail: "終値4,229円(前日比+700円、+19.84%)でストップ高、値上がり率3位。7/28発表の26年4-6月期は売上高+54.7%、営業利益+66.9%、純利益+69.2%と市場予想を上回り、4月発売の新規IP『プラグマタ』が世界250万本超、バイオハザードシリーズも好調だった。4連騰で年初来高値を更新し25年10月29日以来約9カ月ぶりの高値水準。売買代金722.1億円。日経平均が930円安と急落するなかでの逆行高で、資金がゲーム・エンタメに向かった象徴的な動きになった。【朝7:00更新】夜間PTSは4,135円でS高終値を2.22%下回って終了(最終約定23:57)。当日のVWAPは4,113円でS高値を116円下回り、約定回数46,477回・出来高1,755万株と日中に広いレンジで大量に売買が成立した後に引け際でS高に達した形のため、終日買い気配で張り付いた典型パターンではない(＝翌朝の特別気配が長引くリスクは相対的に低い)。また7/29付で野村が目標株価3,600→4,200円、ゴールドマン・サックスが4,200→4,600円へ引き上げたが、終値4,229円は既に野村の新目標を上回っている。",
