            detail: "終値1,318円(前日比+300円、+29.47%)でストップ高。前日28日に続く連日のS高で本日の値上がり率ランキング1位、寄付からの値上がり率でも2位。株探はテーマ区分を『人工知能関連』としている。SNS上では『米エヌビディアのイベントへ同社社長が招待された』という材料を挙げる投稿がある一方、『なんで今日S高なのか全くわからない』という投稿もあり、材料の正体が共有されていない思惑先行の可能性がある。売買代金20.2億円。値動きの荒い小型株で反動安リスクも大きい。",
